const path = require('path');
const { execSync } = require('child_process');
const fs = require('fs');


if(process.platform == "win32") {
  if (process.arch == "x64") {
    module.exports.platform = 'winx64'
  } else {
    module.exports.platform = 'winx86'
  }
} else {
  let platname = undefined
  
  platname = backup_get_platname()

  module.exports.platform = platname
}


function get_platname(){
    // get platform name from releng cplatname script
    let platname = execSync('sh ' + path.join(__dirname, '..', 'cplatname') + ' identify', {encoding:'utf8',stdio:'pipe'});
    return platname
}

function getLinuxDistro() {
  const { execSync } = require('child_process');
  try {
    let distro = execSync('lsb_release -is',{encoding:'utf8',stdio:'pipe'});
    let release = execSync('lsb_release -rs',{encoding:'utf8',stdio:'pipe'});
    return {
      'distro': distro.replace(/(\r\n\t|\n|\r\t)/gm,"").toLowerCase(),
      'release': release.replace(/(\r\n\t|\n|\r\t)/gm,"").toLowerCase()
    };
  } catch (e) {
    return getDistroFromFile();
  }
}

function getDistroFromFile() {
  const fs = require('fs')
  try {
    let osv = fs.readFileSync('/etc/os-release','utf8');
    let lines = osv.split('\n');
    let distro = lines.find((element) => { return element.substring(0,element.indexOf('=')) == 'ID' })
    let release = lines.find((element) => { return element.substring(0,element.indexOf('=')) == 'VERSION_ID' })
    return {
      'distro': distro.substring(distro.indexOf('=') + 1).replace(/["]+/g,''),
      'release': release.substring(release.indexOf('=') + 1).replace(/["]+/g,'')
    };
  } catch (e) {
    return null;
  }
}

function backup_get_platname(){
    if(process.platform == "win32" && process.arch == "x64") {
      // winx64
      return 'winx64'  
    } else if (process.platform == "win32" && process.arch == "ia32") {
      return 'winx86'
    } else if (process.platform == "darwin") {
      if (process.arch == 'x64') {
        return 'macx64'
      } else {
        return 'macos'
      } 
    } else if (process.platform == "linux") {
      let verinfo = getLinuxDistro()
      let distro = verinfo.distro
      let versionID = verinfo.release
      console.log('platform = ' + process.platform + ': ' + distro + ': ' + process.arch);
        if (distro == 'ubuntu') {
          let versionValue = undefined
          if (isRunningInDocker()) {
            versionValue = ''
          } else {
            versionValue = versionID.replace('.', '')
            if (!['1804', '2004', '2204', '2404'].includes(versionValue)) { // not in supported versions 
              versionValue = '' // default to lnxubuntu with no version
            }
          }
			
          if (process.arch == 'arm64') {
            return `lnxubuntu${versionValue}arm64`
          } else if (process.arch == 'x64') {
            return `lnxubuntu${versionValue}x64`
          }
        } else if (distro == 'fedora') {
          return 'lnxrhx64'
        } else if (distro == 'rhx64') {
          return 'lnxrhx64'
        } else if (distro == 'rhel' || distro == 'ol') {
          let major = versionID.split('.')[0]

          if ( process.arch == 'arm64') {
            if (['9', '10'].includes(major)) {
              return `lnxrh${major}arm64`
            } else {
              return 'lnxrharm64'
            }
          } else if (process.arch == 'x64') {
            if (['7', '8', '9', '10'].includes(major)) {
              return `lnxrh${major}x64`
            } else { // default to lnxrhx64
              return 'lnxrhx64'
            }
          }
        } else if (distro == 'sles' && process.arch == 'x64') {
          return 'lnxsuse15x64'
        } else {
            // default to RH for now
            return 'lnxrhx64'
        }
    }
}

function isRunningInDocker() {
  return false
	
	return fs.existsSync('/.dockerenv') 
		|| fs.existsSync('/var/run/docker.sock') 
		|| execSync('cat /proc/1/cgroup', {encoding:'utf8',stdio:'pipe'}).includes('/docker/')
}




